async function fetchWithTimeout(url,ms=11000,textMode=false){const c=new AbortController(),t=setTimeout(()=>c.abort(),ms);try{const r=await fetch(url,{signal:c.signal,cache:'no-store'});if(!r.ok)throw new Error('HTTP '+r.status);return textMode?await r.text():await r.json()}finally{clearTimeout(t)}}
function badge(id,text,kind=''){const e=$(id);if(!e)return;e.textContent=text;e.className='badge'+(kind?' '+kind:'')}
