function aqiBand(v){if(!Number.isFinite(v))return {name:'Unavailable',color:'#7f9bb4'};if(v<=50)return{name:'Good',color:'#4de0ae'};if(v<=100)return{name:'Moderate',color:'#ffc66b'};if(v<=150)return{name:'Unhealthy for sensitive groups',color:'#ff986e'};if(v<=200)return{name:'Unhealthy',color:'#ff647c'};if(v<=300)return{name:'Very unhealthy',color:'#b18aff'};return{name:'Hazardous',color:'#ff5473'}}
function drawLineChart(canvas,series){if(!canvas)return;const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#071421';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#17374b';ctx.lineWidth=1;for(let i=1;i<=4;i++){ctx.beginPath();ctx.moveTo(36,i*(h-36)/5);ctx.lineTo(w-12,i*(h-36)/5);ctx.stroke()}const all=series.flatMap(x=>x.values).filter(Number.isFinite);if(all.length<2){ctx.fillStyle='#7f9bb4';ctx.font='13px system-ui';ctx.fillText('No valid model series available',18,30);return}const mn=Math.min(0,...all),mx=Math.max(...all)*1.1||1;const colors=['#44e2ee','#ffc66b','#9a83ff'];series.forEach((s,j)=>{const vals=s.values.filter(Number.isFinite);if(vals.length<2)return;ctx.strokeStyle=colors[j%colors.length];ctx.lineWidth=2.5;ctx.beginPath();vals.forEach((v,i)=>{const x=36+i*(w-52)/(vals.length-1),y=h-24-(v-mn)/(mx-mn||1)*(h-54);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke()});ctx.fillStyle='#9ab6c9';ctx.font='11px system-ui';ctx.fillText('Max '+fmt(mx,1),38,15);ctx.fillText('0',7,h-22);let lx=46;series.forEach((s,i)=>{ctx.fillStyle=['#44e2ee','#ffc66b','#9a83ff'][i%3];ctx.fillRect(lx, h-13, 10, 3);ctx.fillStyle='#9ab6c9';ctx.fillText(s.label,lx+14,h-9);lx+=Math.min(210,ctx.measureText(s.label).width+40)})}
async function loadAir(latOverride=null,lonOverride=null,nameOverride=null){const point=latOverride!==null?{lat:Number(latOverride),lon:Number(lonOverride),name:nameOverride||'Device location'}:coordsFromSelect('aqLocation');if(!Number.isFinite(point.lat)||!Number.isFinite(point.lon)||Math.abs(point.lat)>90||Math.abs(point.lon)>180){status('aqMessage','Invalid coordinates. Check the selected reference location.','bad');return}badge('aqStatus','FETCHING','sim');status('aqMessage','Requesting model fields from Open-Meteo…');const url='https://air-quality-api.open-meteo.com/v1/air-quality?latitude='+encodeURIComponent(point.lat)+'&longitude='+encodeURIComponent(point.lon)+'&current=pm10,pm2_5,us_aqi,european_aqi,ozone,nitrogen_dioxide&hourly=pm2_5,pm10,us_aqi&forecast_days=2&timezone=Asia%2FDhaka';try{const d=await fetchWithTimeout(url);if(!d.current||!d.hourly)throw new Error('Required air-quality fields missing');lastAir={...d,queryPoint:point,receivedAt:new Date().toISOString(),url};const c=d.current,aqi=Number(c.us_aqi),band=aqiBand(aqi);const aqThreshold=Math.max(0,Math.min(500,Number($('aqAlertThreshold')?.value||150)));if(!$('aqAlertEnabled')?.checked)airAboveThreshold=false;else if(Number.isFinite(aqi)&&aqi>=aqThreshold&&!airAboveThreshold){window.dispatchEvent(new CustomEvent('terravex:advanced-alert',{detail:{type:'AIR QUALITY MODEL',title:'Air-quality model crossed selected threshold',detail:point.name+' · model US AQI '+Math.round(aqi)+' reached configured threshold '+aqThreshold+'. This is modeled data, not a regulatory station alert.',level:aqi>=200?'high':'warn',source:'Open-Meteo/CAMS model',id:'aqi-'+point.lat.toFixed(3)+'-'+point.lon.toFixed(3)+'-'+Math.floor(Date.now()/3600000),notify:true}}));airAboveThreshold=true;}else if(Number.isFinite(aqi)&&aqi<aqThreshold)airAboveThreshold=false;$('aqCity').textContent=point.name;$('aqIndex').textContent=Number.isFinite(aqi)?Math.round(aqi):'—';$('aqCategory').textContent=band.name;$('aqGauge').style.background='conic-gradient('+band.color+' 0 100%)';$('aqPm25').textContent=fmt(Number(c.pm2_5),1);$('aqPm10').textContent=fmt(Number(c.pm10),1);$('aqOzone').textContent=fmt(Number(c.ozone),1);$('aqNo2').textContent=fmt(Number(c.nitrogen_dioxide),1);$('aqEuIndex').textContent=fmt(Number(c.european_aqi),0);$('aqGrid').textContent=fmt(Number(d.latitude),3)+', '+fmt(Number(d.longitude),3);$('aqStamp').textContent='Model time: '+(c.time||'not supplied')+' · retrieved '+new Date(lastAir.receivedAt).toLocaleString();const times=d.hourly.time||[],vals=(d.hourly.pm2_5||[]).slice(0,24).map(Number),pm10=(d.hourly.pm10||[]).slice(0,24).map(Number);drawLineChart($('aqChart'),[{label:'PM2.5 µg/m³',values:vals},{label:'PM10 µg/m³',values:pm10}]);badge('aqStatus','MODEL RESPONSE','sim');status('Model response received. This is CAMS-based model output, not a direct air-monitor measurement. AQI bands shown here are the US AQI categories from the API, not Bangladesh regulatory grading.','good');return true}catch(e){badge('aqStatus','OFFLINE','warn');status('Air-quality endpoint unavailable: '+String(e.message||e)+'. No readings have been invented.','bad');return false}}
