const evtType=e=>{const cats=(e.categories||[]).map(c=>(c.id||c.title||'').toLowerCase()).join(' ');if(cats.includes('storm'))return'storm';if(cats.includes('wildfire')||cats.includes('fire'))return'fire';if(cats.includes('volcano'))return'volcano';return'other'};
