function drawEonet(){const c=$('eonetCanvas');if(!c)return;const ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#061421';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#18374b';ctx.lineWidth=1;for(let lon=-150;lon<=150;lon+=30){const x=(lon+180)/360*w;ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke()}for(let lat=-60;lat<=60;lat+=30){const y=(90-lat)/180*h;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}// Low-detail continent silhouettes are schematic, not boundary data.
const polys=[[[-168,70],[-130,72],[-105,55],[-80,48],[-60,20],[-82,5],[-110,25],[-130,50]],[[-80,12],[-50,5],[-35,-20],[-70,-55],[-80,-20]],[[-18,35],[40,35],[52,5],[30,-35],[10,-30],[-5,0]],[[-10,70],[50,65],[145,55],[170,40],[120,10],[95,0],[75,20],[45,30],[15,45]],[ [112,-12],[155,-10],[150,-40],[120,-45] ]];ctx.fillStyle='#183a4a';ctx.strokeStyle='#2a6074';for(const p of polys){ctx.beginPath();p.forEach(([lon,lat],i)=>{const x=(lon+180)/360*w,y=(90-lat)/180*h;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.closePath();ctx.fill();ctx.stroke()}const filtered=lastEvents.filter(e=>{const sel=$('eonetFilter')?.value||'all';return sel==='all'||(e.categories||[]).some(c=>c.id===sel||c.title?.toLowerCase().replaceAll(' ','')===sel.toLowerCase())});filtered.forEach(e=>{const p=eventPoint(e);if(!p||Math.abs(p.lat)>90||Math.abs(p.lon)>180)return;const x=(p.lon+180)/360*w,y=(90-p.lat)/180*h,t=evtType(e),color=t==='storm'?'#44e2ee':t==='fire'?'#ff986e':t==='volcano'?'#ff647c':'#b9a0ff';ctx.beginPath();ctx.fillStyle=color;ctx.shadowColor=color;ctx.shadowBlur=9;ctx.arc(x,y,4,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.beginPath();ctx.strokeStyle=color+'99';ctx.arc(x,y,8,0,Math.PI*2);ctx.stroke()});ctx.fillStyle='#8caabe';ctx.font='12px system-ui';ctx.fillText(filtered.length+' returned open event(s) · schematic geographic plot',12,h-12)}
function renderEvents(){const sel=$('eonetFilter')?.value||'all',list=lastEvents.filter(e=>sel==='all'||(e.categories||[]).some(c=>c.id===sel||c.title?.toLowerCase().replaceAll(' ','')===sel.toLowerCase()));$('eonetCount').textContent=lastEvents.length;$('eonetStorms').textContent=lastEvents.filter(e=>evtType(e)==='storm').length;$('eonetFires').textContent=lastEvents.filter(e=>evtType(e)==='fire').length;$('eonetVolcanoes').textContent=lastEvents.filter(e=>evtType(e)==='volcano').length;drawEonet();const host=$('eonetList');if(!host)return;if(!list.length){host.innerHTML='<div class="muted">No matching open events in this response. This does not mean no hazards exist.</div>';return}host.innerHTML=list.slice(0,70).map(e=>{const p=eventPoint(e),type=evtType(e),icon=type==='storm'?'ϟ':type==='fire'?'♨':type==='volcano'?'△':'◉',cat=(e.categories||[]).map(c=>c.title||c.id).join(', ')||'Uncategorized',time=p?.date?new Date(p.date).toLocaleString():'Time unavailable';const link=e.link||'https://eonet.gsfc.nasa.gov/docs/v3';return '<article class="adv-event"><span class="adv-event-icon">'+icon+'</span><div><b>'+esc(e.title||'Untitled natural event')+'</b><small>'+esc(cat)+' · '+esc(time)+'</small><small>'+(p?fmt(p.lat,2)+'°, '+fmt(p.lon,2)+'°':'No point coordinate in latest geometry')+'</small><a href="'+esc(link)+'" target="_blank" rel="noopener">SOURCE RECORD ↗</a></div></article>'}).join('')}
