/* TERRAVEX ENGINEERING STUDIO v42 — conceptual architectural planning only. */
(()=>{'use strict';
 const $=id=>document.getElementById(id);
 const LENGTH={m:1,ft:0.3048,cm:0.01,mm:0.001,km:1000};
 const AREA={m2:1,ft2:0.09290304,acre:4046.8564224,ha:10000,decimal:40.468564224,km2:1000000};
 const AREA_LABEL={m2:'m²',ft2:'ft²',acre:'ac',ha:'ha',decimal:'decimal',km2:'km²'};
 const FMT=(n,d=2)=>Number.isFinite(n)?n.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
 let latest=null,raf=0,angle=0,lastFrame=0,entered=false,earthEntities=[];
 const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
 function input(id){const e=$(id);return e?e.value:'';}
 function calculateScenario(x){
   const shape=x.shape||'rectangle',unit=x.lengthUnit||'m',fac=LENGTH[unit];
   if(!fac)throw new Error('Unsupported dimension unit.');
   const a=Number(x.dimA)*fac,b=Number(x.dimB)*fac;
   if(!Number.isFinite(a)||a<=0||a>100000)throw new Error('Plot dimension A must be a positive, finite value.');
   let area=0,perimeter=0,sitePoints=[];
   if(shape==='rectangle'){
     if(!Number.isFinite(b)||b<=0||b>100000)throw new Error('Rectangle width must be a positive, finite value.');
     area=a*b;perimeter=2*(a+b);sitePoints=[[-a/2,-b/2],[a/2,-b/2],[a/2,b/2],[-a/2,b/2]];
   }else if(shape==='triangle'){
     if(!Number.isFinite(b)||b<=0||b>100000)throw new Error('Right-triangle perpendicular height must be positive.');
     area=.5*a*b;perimeter=a+b+Math.hypot(a,b);sitePoints=[[-a/2,-b/3],[a/2,-b/3],[-a/2,2*b/3]];
   }else if(shape==='circle'){
     const r=a/2;area=Math.PI*r*r;perimeter=2*Math.PI*r;sitePoints=Array.from({length:64},(_,i)=>{const t=2*Math.PI*i/64;return [r*Math.cos(t),r*Math.sin(t)]});
   }else throw new Error('Choose rectangle, right triangle or circle.');
   const floors=Number(x.floors),floorHeight=Number(x.floorHeight),coverage=Number(x.coverage),glazing=Number(x.glazingRatio),waste=Number(x.waste);
   if(!Number.isInteger(floors)||floors<1||floors>100)throw new Error('Concept storeys must be an integer from 1 to 100.');
   if(!Number.isFinite(floorHeight)||floorHeight<2||floorHeight>8)throw new Error('Floor-to-floor height must be between 2 and 8 metres.');
   if(!Number.isFinite(coverage)||coverage<1||coverage>100)throw new Error('Target coverage must be between 1 and 100%.');
   if(!Number.isFinite(glazing)||glazing<0||glazing>90)throw new Error('Facade glazing allowance must be between 0 and 90%.');
   if(!Number.isFinite(waste)||waste<0||waste>30)throw new Error('Finish allowance must be between 0 and 30%.');
   const footprint=area*coverage/100,gfa=footprint*floors,height=floors*floorHeight,far=gfa/area;
   const farLimit=x.farLimit===''||x.farLimit==null?null:Number(x.farLimit);
   const coverageLimit=x.coverageLimit===''||x.coverageLimit==null?null:Number(x.coverageLimit);
   const heightLimit=x.heightLimit===''||x.heightLimit==null?null:Number(x.heightLimit);
   for(const [v,n] of [[farLimit,'FAR'],[coverageLimit,'coverage limit'],[heightLimit,'height limit']])if(v!==null&&(!Number.isFinite(v)||v<=0))throw new Error(n+' must be blank or a positive value.');
   const areaUnit=x.areaUnit||'m2';if(!AREA[areaUnit])throw new Error('Unsupported area unit.');
   const facadeGross=perimeter*Math.sqrt(coverage/100)*height;
   const multiplier=1+waste/100;
   const finishes=[
     {name:'Floor finish (tile / stone / equivalent)',basis:'Gross floor area × finish allowance',qty:gfa*multiplier},
     {name:'Ceiling finish (non-structural)',basis:'Gross floor area × finish allowance',qty:gfa*multiplier},
     {name:'Roof waterproofing membrane',basis:'Concept footprint × finish allowance',qty:footprint*multiplier},
     {name:'Opaque facade finish / cladding',basis:'Approx. facade envelope × (1 − glazing ratio) × allowance',qty:facadeGross*(1-glazing/100)*multiplier},
     {name:'Glazing surface allowance',basis:'Approx. facade envelope × glazing ratio × allowance',qty:facadeGross*(glazing/100)*(1+waste/100)}
   ];
   const flags=[];
   if(farLimit===null)flags.push({kind:'neutral',title:'FAR not assessed',text:'Enter the verified local FAR limit and applicable use/zone before planning review.'});
   else flags.push(far<=farLimit?{kind:'good',title:'Within entered FAR scenario',text:'Calculated FAR '+FMT(far,2)+' versus user-entered limit '+FMT(farLimit,2)+'. This is not authority approval.'}:{kind:'bad',title:'Above entered FAR scenario',text:'Calculated FAR '+FMT(far,2)+' exceeds the user-entered limit '+FMT(farLimit,2)+'. Revise concept or verify applicable rules.'});
   if(coverageLimit===null)flags.push({kind:'neutral',title:'Coverage limit not assessed',text:'Actual site coverage, open space and setbacks must be verified with the local authority.'});
   else flags.push(coverage<=coverageLimit?{kind:'good',title:'Within entered coverage scenario',text:'Target coverage '+FMT(coverage,1)+'% versus entered limit '+FMT(coverageLimit,1)+'%.'}:{kind:'bad',title:'Above entered coverage scenario',text:'Target coverage '+FMT(coverage,1)+'% exceeds entered limit '+FMT(coverageLimit,1)+'%.'});
   if(heightLimit===null)flags.push({kind:'neutral',title:'Height limit not assessed',text:'Height, aviation restrictions, fire access and local zoning have not been verified.'});
   else flags.push(height<=heightLimit?{kind:'good',title:'Within entered height scenario',text:'Concept height '+FMT(height,2)+' m versus entered limit '+FMT(heightLimit,2)+' m.'}:{kind:'bad',title:'Above entered height scenario',text:'Concept height '+FMT(height,2)+' m exceeds entered limit '+FMT(heightLimit,2)+' m.'});
   flags.push({kind:'warn',title:'Structural feasibility is not evaluated',text:'No wind/seismic analysis, soil capacity, foundation, fire engineering or reinforcement design is generated.'});
   return {shape,unit,areaUnit,dimA:Number(x.dimA),dimB:shape==='circle'?null:Number(x.dimB),a,b,plotArea:area,perimeter,sitePoints,coverage,footprint,floors,floorHeight,height,gfa,far,farLimit,coverageLimit,heightLimit,glazingRatio:glazing,waste,facadeGross,finishes,flags,buildingUse:x.buildingUse||'residential',createdAt:new Date().toISOString()};
 }
 function collect(){return {shape:input('engShape'),lengthUnit:input('engLengthUnit'),areaUnit:input('engAreaUnit'),dimA:input('engDimA'),dimB:input('engDimB'),floors:input('engFloors'),floorHeight:input('engFloorHeight'),coverage:input('engCoverage'),farLimit:input('engFarLimit'),coverageLimit:input('engCoverageLimit'),heightLimit:input('engHeightLimit'),glazingRatio:input('engGlazingRatio'),waste:input('engWaste'),buildingUse:input('engUse')};}
 function areaFormat(v,unit){const d=v/AREA[unit];return FMT(d,unit==='m2'||unit==='ft2'?1:4)+' '+AREA_LABEL[unit];}
 function set(id,value){const e=$(id);if(e)e.textContent=value;}
 function badge(id,label,kind){const e=$(id);if(e){e.textContent=label;e.className='badge '+(kind||'');}}
 function updateShapeInputs(){const shape=input('engShape'),la=$('engDimALabel'),lb=$('engDimBLabel'),b=$('engDimB');if(!la||!lb||!b)return;if(shape==='circle'){la.textContent='Plot diameter';lb.textContent='Not used for circular plot';b.disabled=true;}else if(shape==='triangle'){la.textContent='Triangle base';lb.textContent='Perpendicular height';b.disabled=false;}else{la.textContent='Plot length';lb.textContent='Plot width';b.disabled=false;}}
 function projectPoint(pt,z,scale,cx,cy,rot){const x=pt[0]*Math.cos(rot)-pt[1]*Math.sin(rot),y=pt[0]*Math.sin(rot)+pt[1]*Math.cos(rot);return {x:cx+x*scale,y:cy+y*scale*.48-z*scale*.42};}
 function drawMassing(result,advance=false){const c=$('engMassCanvas');if(!c||!result)return;const ctx=c.getContext('2d');if(!ctx)return;const w=c.width,h=c.height;ctx.clearRect(0,0,w,h);const bg=ctx.createLinearGradient(0,0,w,h);bg.addColorStop(0,'#071522');bg.addColorStop(.55,'#0b1d31');bg.addColorStop(1,'#06111e');ctx.fillStyle=bg;ctx.fillRect(0,0,w,h);ctx.strokeStyle='rgba(79,166,208,.10)';ctx.lineWidth=1;for(let x=0;x<w;x+=55){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke()}for(let y=0;y<h;y+=42){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}
   if(advance&&$('engAutoRotate')?.checked)angle=(angle+.0024)%(Math.PI*2);const render=input('engRenderMode')||'glass',maxDim=Math.max(...result.sitePoints.map(p=>Math.hypot(p[0],p[1])),1),scale=Math.min(w*.33/maxDim,h*.50/(maxDim*.96+result.height*.42)),cx=w*.49,cy=h*.70,fpScale=Math.sqrt(result.coverage/100),base=result.sitePoints.map(p=>[p[0]*fpScale,p[1]*fpScale]);
   const ground=result.sitePoints.map(p=>projectPoint(p,0,scale,cx,cy,angle));ctx.beginPath();ground.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle='rgba(32,104,128,.08)';ctx.fill();ctx.strokeStyle='rgba(80,190,220,.5)';ctx.setLineDash([7,5]);ctx.stroke();ctx.setLineDash([]);
   const top=base.map(p=>projectPoint(p,result.height,scale,cx,cy,angle)),bottom=base.map(p=>projectPoint(p,0,scale,cx,cy,angle));const faces=base.map((_,i)=>({i,depth:(bottom[i].y+bottom[(i+1)%base.length].y)/2})).sort((a,b)=>a.depth-b.depth);
   for(const f of faces){const i=f.i,j=(i+1)%base.length,p=[bottom[i],bottom[j],top[j],top[i]];ctx.beginPath();ctx.moveTo(p[0].x,p[0].y);p.slice(1).forEach(v=>ctx.lineTo(v.x,v.y));ctx.closePath();const grad=ctx.createLinearGradient(p[0].x,p[0].y,p[2].x,p[2].y);grad.addColorStop(0,render==='solid'?'#1d6680':render==='wire'?'rgba(0,0,0,0)':'rgba(57,204,228,.38)');grad.addColorStop(1,render==='solid'?'#0e304b':render==='wire'?'rgba(0,0,0,0)':'rgba(30,111,160,.18)');ctx.fillStyle=grad;ctx.fill();ctx.strokeStyle=render==='wire'?'#72d9ef':'rgba(117,219,239,.76)';ctx.lineWidth=render==='wire'?1.5:1;ctx.stroke();if(render!=='wire'){for(let k=1;k<result.floors;k++){const t=k/result.floors;const a={x:bottom[i].x+(top[i].x-bottom[i].x)*t,y:bottom[i].y+(top[i].y-bottom[i].y)*t},b={x:bottom[j].x+(top[j].x-bottom[j].x)*t,y:bottom[j].y+(top[j].y-bottom[j].y)*t};ctx.strokeStyle='rgba(181,232,242,.23)';ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke()}}}
   ctx.beginPath();top.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle=render==='wire'?'rgba(0,0,0,0)':'rgba(95,216,231,.24)';ctx.fill();ctx.strokeStyle='#a2f3ff';ctx.lineWidth=2;ctx.stroke();
   ctx.fillStyle='#bce9f7';ctx.font='bold 19px system-ui';ctx.fillText(result.floors+' STOREY CONCEPT',30,42);ctx.fillStyle='#7faec4';ctx.font='12px ui-monospace,monospace';ctx.fillText(result.shape.toUpperCase()+' · '+FMT(result.height,2)+' M · '+FMT(result.gfa,0)+' M² GFA',30,66);ctx.fillText('SCHEMATIC MASSING / NOT A STRUCTURAL MODEL',30,h-24);
   if(advance&&$('engAutoRotate')?.checked)raf=requestAnimationFrame(t=>drawMassing(result,true));
 }
 function render(result){latest=result;const unit=result.areaUnit;set('engOutPlot',areaFormat(result.plotArea,unit));set('engOutPlotSI',FMT(result.plotArea,2)+' m²');set('engOutFootprint',areaFormat(result.footprint,unit));set('engOutGFA',areaFormat(result.gfa,unit));set('engOutHeight',FMT(result.height,2)+' m');set('engOutFAR',FMT(result.far,3));set('engOutFARState',result.farLimit===null?'Limit not supplied':'Entered limit '+FMT(result.farLimit,2));set('engOutPerimeter',FMT(result.perimeter,2)+' m');set('engVisualShape',result.shape.toUpperCase()+' MASSING');set('engVisualFloors',result.floors+' STOREYS');set('engVisualHeight',FMT(result.height,2)+' M');const host=$('engFeasibilityFlags');host.innerHTML=result.flags.map(f=>'<div class="eng-flag '+f.kind+'"><b>'+f.title+'</b><span>'+f.text+'</span></div>').join('');badge('engFeasibilityBadge',result.flags.some(f=>f.kind==='bad')?'SCENARIO LIMIT EXCEEDED':'CONCEPT CHECKED',result.flags.some(f=>f.kind==='bad')?'warn':'sim');const body=$('engFinishRows');body.innerHTML=result.finishes.map(f=>'<tr><td>'+f.name+'</td><td>'+f.basis+'</td><td>'+FMT(f.qty,1)+' m²</td></tr>').join('');set('engTimestamp','Calculated '+new Date(result.createdAt).toLocaleString());set('engLiveState','SCENARIO RECALCULATED');const msg=$('engInputMessage');if(msg)msg.textContent='Concept recalculated. All results are preliminary planning quantities, not a construction BOQ or an engineering approval.';drawMassing(result);if(entered&&$('engAutoRotate')?.checked&&!raf)drawMassing(result,true);}
 function calculate(){try{const r=calculateScenario(collect());render(r);return r;}catch(e){badge('engFeasibilityBadge','INPUT ERROR','warn');set('engLiveState','INPUT ERROR');const m=$('engInputMessage');if(m)m.textContent=e.message;return null;}}
 function pstr(n){return (Math.abs(n)<1e-9?0:n).toFixed(4);}
 function dxfEntityPolyline(points,z,layer){let s='0\nPOLYLINE\n8\n'+layer+'\n66\n1\n70\n9\n';for(const pt of points){s+='0\nVERTEX\n8\n'+layer+'\n10\n'+pstr(pt[0])+'\n20\n'+pstr(pt[1])+'\n30\n'+pstr(z)+'\n70\n32\n';}return s+'0\nSEQEND\n8\n'+layer+'\n';}
 function dxfFace(points,layer){const p=points.length===3?[...points,points[2]]:points;let s='0\n3DFACE\n8\n'+layer+'\n';for(let i=0;i<4;i++)s+=(10+i)+'\n'+pstr(p[i][0])+'\n'+(20+i)+'\n'+pstr(p[i][1])+'\n'+(30+i)+'\n'+pstr(p[i][2])+'\n';return s;}
 function buildDxf(r){const sc=Math.sqrt(r.coverage/100),foot=r.sitePoints.map(p=>[p[0]*sc,p[1]*sc]),z=r.height;let out='0\nSECTION\n2\nHEADER\n9\n$ACADVER\n1\nAC1015\n9\n$INSUNITS\n70\n6\n0\nENDSEC\n0\nSECTION\n2\nTABLES\n0\nTABLE\n2\nLAYER\n70\n5\n';for(const [name,color] of [['SITE',8],['FOOTPRINT',4],['MASSING',5],['LEVELS',3],['NOTES',7]])out+='0\nLAYER\n2\n'+name+'\n70\n0\n62\n'+color+'\n6\nCONTINUOUS\n';out+='0\nENDTAB\n0\nENDSEC\n0\nSECTION\n2\nENTITIES\n';out+=dxfEntityPolyline(r.sitePoints,0,'SITE')+dxfEntityPolyline(foot,0,'FOOTPRINT');out+=dxfEntityPolyline(foot,z,'MASSING');for(let k=1;k<r.floors;k++)out+=dxfEntityPolyline(foot,z*k/r.floors,'LEVELS');for(let i=0;i<foot.length;i++){const j=(i+1)%foot.length;out+=dxfFace([[foot[i][0],foot[i][1],0],[foot[j][0],foot[j][1],0],[foot[j][0],foot[j][1],z],[foot[i][0],foot[i][1],z]],'MASSING');}for(let i=1;i<foot.length-1;i++)out+=dxfFace([[foot[0][0],foot[0][1],z],[foot[i][0],foot[i][1],z],[foot[i+1][0],foot[i+1][1],z]],'MASSING');out+='0\nTEXT\n8\nNOTES\n10\n0\n20\n'+pstr(Math.max(...r.sitePoints.map(p=>p[1]))+2)+'\n30\n0\n40\n1.5\n1\nTERRAVEX CONCEPT MASSING - NOT FOR CONSTRUCTION\n0\nENDSEC\n0\nEOF\n';return out;}
 function download(name,data,type){const blob=new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
 function exportDxf(){const r=latest||calculate();if(!r)return;download('terravex-concept-massing-not-for-construction.dxf',buildDxf(r),'application/dxf');set('engInputMessage','Conceptual DXF exported in metre units. It contains plot boundary and schematic massing only; no structure or reinforcement.');}
 function csvEscape(s){return '"'+String(s).replace(/"/g,'""')+'"';}
 function exportCsv(){const r=latest||calculate();if(!r)return;const rows=[['Item','Basis','Quantity','Unit','Classification'],...r.finishes.map(f=>[f.name,f.basis,FMT(f.qty,3),'m2','Non-structural preliminary allowance'])];download('terravex-non-structural-finish-allowance.csv','\ufeff'+rows.map(row=>row.map(csvEscape).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
 function exportJson(){const r=latest||calculate();if(!r)return;const report={application:'TERRAVEX APEX Engineering Studio',classification:'Concept-stage feasibility and non-structural finish allowances only; not for construction or tender',scenario:r,limitations:['No reinforcement, beams, columns, foundations, structural steel, load path or structural concrete quantities','No code approval, soil capacity, groundwater, seismic or wind design','No military/naval/weapons facility design','Satellite and regional soil maps do not replace geotechnical investigation']};download('terravex-engineering-concept-report.json',JSON.stringify(report,null,2),'application/json');}
 function clearEarthMassing(){const mod=window.TERRAVEX_EARTH_COMMAND,v=mod?.getViewer?.();if(v&&v.entities){for(const entity of earthEntities){try{v.entities.remove(entity)}catch{}}}earthEntities=[];const m=$('engInputMessage');if(m)m.textContent='Terravex concept geometry has been removed from the shared 3D Earth. The Earth imagery and all existing layers are unchanged.';}
 function plotMassingOnEarth(r,lat,lon){const mod=window.TERRAVEX_EARTH_COMMAND,C=mod?.getCesium?.(),v=mod?.getViewer?.();if(!C||!v||!v.entities)throw new Error('The existing Cesium 3D Earth viewer is not ready. Open Live 3D Earth once, then retry.');if(Math.max(r.a||0,r.b||0)>20000)throw new Error('The shared-globe parcel overlay is limited to local concept plots up to 20 km across; use a surveyed GIS polygon for regional projects.');clearEarthMassing();const cosLat=Math.max(.15,Math.cos(lat*Math.PI/180)),toGeo=pt=>[lon+(pt[0]/(111320*cosLat)),lat+(pt[1]/110540)];const plot=r.sitePoints.map(toGeo),scale=Math.sqrt(r.coverage/100),foot=r.sitePoints.map(pt=>toGeo([pt[0]*scale,pt[1]*scale]));const closed=pts=>pts.concat([pts[0]]);const siteLine=closed(plot).flatMap(pt=>pt);const sitePositions=C.Cartesian3.fromDegreesArray(siteLine);const entityStyle=C.Color?.fromCssColorString?C.Color.fromCssColorString('#55d8f4'):C.Color.CYAN;const siteEntity=v.entities.add({name:'TERRAVEX concept parcel boundary (schematic)',polyline:{positions:sitePositions,width:2,material:entityStyle.withAlpha(.85),clampToGround:true}});earthEntities.push(siteEntity);const footprintPositions=C.Cartesian3.fromDegreesArray(foot.flatMap(pt=>pt));const groundHeight=v.scene?.globe?.getHeight?.(C.Cartographic.fromDegrees(lon,lat))||0;const building=v.entities.add({name:'TERRAVEX conceptual building massing — NOT FOR CONSTRUCTION',polygon:{hierarchy:footprintPositions,height:groundHeight,extrudedHeight:groundHeight+r.height,material:entityStyle.withAlpha(.28),outline:true,outlineColor:entityStyle.withAlpha(.95)}});earthEntities.push(building);if(r.floors<=100){for(let k=1;k<r.floors;k++){const z=groundHeight+k*r.floorHeight,level=closed(foot).map(pt=>C.Cartesian3.fromDegrees(pt[0],pt[1],z));const levelEntity=v.entities.add({name:'Concept floor level '+(k+1)+' (visual only)',polyline:{positions:level,width:1,material:entityStyle.withAlpha(.40)}});earthEntities.push(levelEntity);}}const siteDiagonal=Math.hypot(r.a||0,r.b||0);const cameraHeight=Math.min(100000,Math.max(1800,siteDiagonal*2.2+r.height*2.5));v.camera.flyTo({destination:C.Cartesian3.fromDegrees(lon,lat,cameraHeight),duration:1.6});v.scene?.requestRender?.();return earthEntities.length;}
 async function openSiteInEarth(){const r=latest||calculate();if(!r)return;const lat=Number(input('engLatitude')),lon=Number(input('engLongitude'));if(input('engLatitude')===''||input('engLongitude')===''||!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180){const m=$('engInputMessage');if(m)m.textContent='Enter valid site latitude and longitude first. Coordinates must come from a survey or a user-authorized source; the app does not verify plot boundaries.';return;}document.querySelector('.nav button[data-page=\"earthcommand\"]')?.click();const m=$('engInputMessage');if(m)m.textContent='Opening the shared 3D Earth and preparing the conceptual building overlay…';for(let attempt=0;attempt<32;attempt++){const mod=window.TERRAVEX_EARTH_COMMAND,C=mod?.getCesium?.(),v=mod?.getViewer?.();if(C&&v&&v.entities){try{const n=plotMassingOnEarth(r,lat,lon);if(m)m.textContent='Concept massing plotted on the existing Cesium 3D Earth ('+n+' visual entities). Plot geometry is schematic and coordinates are user-supplied; it is not a surveyed or structural design.';return;}catch(e){if(m)m.textContent=e.message;return;}}await new Promise(resolve=>setTimeout(resolve,250));}if(m)m.textContent='The shared 3D Earth did not become ready. Check the Cesium script/network status, open Live 3D Earth once, then retry.';}

 function enter(){entered=true;if(!latest){updateShapeInputs();calculate();}else if(latest)drawMassing(latest,true);}
 function leave(){entered=false;if(raf){cancelAnimationFrame(raf);raf=0;}if(latest)drawMassing(latest,false);}
 function queueCalculation(){clearTimeout(calcTimer);set('engLiveState','CALCULATING FROM INPUTS');badge('engFeasibilityBadge','UPDATING SCENARIO','sim');calcTimer=setTimeout(()=>{calcTimer=0;calculate()},160);}
 function init(){if(!$('page-engineering'))return;$('engShape')?.addEventListener('change',()=>{updateShapeInputs();calculate()});['engAreaUnit','engLengthUnit','engUse'].forEach(id=>$(id)?.addEventListener('change',queueCalculation));$('engRenderMode')?.addEventListener('change',()=>{if(latest)drawMassing(latest)});$('engAutoRotate')?.addEventListener('change',()=>{if(!$('engAutoRotate').checked&&raf){cancelAnimationFrame(raf);raf=0;}else if(latest&&!raf)drawMassing(latest,true)});$('engViewReset')?.addEventListener('click',()=>{angle=0;if(latest)drawMassing(latest)});$('engCalculate')?.addEventListener('click',calculate);$('engRunScenario')?.addEventListener('click',calculate);$('engReset')?.addEventListener('click',()=>{const d={engUse:'residential',engShape:'rectangle',engLengthUnit:'m',engAreaUnit:'m2',engDimA:30,engDimB:20,engFloors:8,engFloorHeight:3.3,engCoverage:45,engFarLimit:'',engCoverageLimit:'',engHeightLimit:'',engGlazingRatio:35,engWaste:5,engLatitude:'',engLongitude:''};for(const [id,v] of Object.entries(d))if($(id))$(id).value=v;updateShapeInputs();calculate()});$('engExportDxf')?.addEventListener('click',exportDxf);$('engExportCsv')?.addEventListener('click',exportCsv);$('engExportJson')?.addEventListener('click',exportJson);$('engExportReport')?.addEventListener('click',exportJson);$('engOpenEarth')?.addEventListener('click',openSiteInEarth);$('engClearEarth')?.addEventListener('click',clearEarthMassing);['engDimA','engDimB','engFloors','engFloorHeight','engCoverage','engFarLimit','engCoverageLimit','engHeightLimit','engGlazingRatio','engWaste'].forEach(id=>$(id)?.addEventListener('input',queueCalculation));calculate();}
 window.TERRAVEX_ENGINEERING_STUDIO={enter,leave,calculate,calculateScenario,buildDxf,plotMassingOnEarth,clearEarthMassing,getLatest:()=>latest};
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();
